/*\n  # Fix notifications_type_check constraint to include task_assigned and task_completed\n\n  The task assignment trigger inserts notifications with type 'task_assigned' and 'task_completed',\n  but these types were missing from the CHECK constraint, causing insert failures when creating tasks\n  with assignments.\n\n  Changes:\n  - Drops and recreates notifications_type_check to include 'task_assigned' and 'task_completed'\n  - Preserves all 27 existing allowed types\n*/\n\nALTER TABLE notifications DROP CONSTRAINT IF EXISTS notifications_type_check

\n\nALTER TABLE notifications ADD CONSTRAINT notifications_type_check CHECK (\n  type = ANY (ARRAY[\n    'lead',\n    'task',\n    'task_assigned',\n    'task_completed',\n    'appointment',\n    'proposal',\n    'invoice',\n    'message',\n    'work_order',\n    'service_request',\n    'review_request',\n    'punchlist',\n    'test_tune',\n    'product_request',\n    'work_order_assignment',\n    'proposal_message',\n    'bug_report',\n    'paparazzi_photos_uploaded',\n    'vip_signup',\n    'time_adjustment_request',\n    'home_clock',\n    'proposal_approval',\n    'auto_clock_out',\n    'punchlist_service_request',\n    'service_request_created',\n    'system',\n    'mileage_reminder',\n    'service_request_kicked_back',\n    'service_request_resubmitted'\n  ])\n)

\n
